        if (artifactRepoUrl != null) {
            maven {
                url artifactRepoUrl
                credentials {
                    username = System.getenv("ARTIFACTORY_USER")
                    password = System.getenv("ARTIFACTORY_PASS")
                }
            }
        }
        else {
            mavenCentral()
            maven { url = "https://plugins.gradle.org/m2/" }
        }
    }
    dependencies {
        classpath("org.jetbrains.kotlin:kotlin-gradle-plugin:${kotlinVersion}")
        classpath("org.jetbrains.kotlin:kotlin-allopen:${kotlinVersion}")
        classpath("org.owasp:dependency-check-gradle:13.0.0")
        classpath("org.springframework.boot:spring-boot-gradle-plugin:$springBootVersion")
    }
}

apply plugin: DependenciesGraphPlugin
apply plugin: "org.owasp.dependencycheck"

dependencyUpdates.resolutionStrategy = {
    componentSelection { rules ->
        rules.all { ComponentSelection selection ->
            boolean rejected = ['alpha', 'beta', 'rc', 'cr', 'm'].any { qualifier ->
                selection.candidate.version ==~ /(?i).*[.-]${qualifier}[.\d-]*/
            }
            if (rejected) {
                selection.reject('Release candidate')
            }
        }
    }
}

subprojects {
    configurations {
        ktlint
    }
    dependencies {
        ktlint "com.pinterest.ktlint:ktlint-cli:1.8.0"
    }
    // Prevent Spring Boot's dependency-management plugin (which imports kotlin-bom via
    // spring-boot-dependencies) from forcing ktlint's internal compiler dependencies
    // (such as kotlin-compiler-embeddable) to match the project's kotlinVersion.
    // Ktlint CLI must run with its own bundled/requested dependency versions.
    afterEvaluate {
        configurations.ktlint.resolutionStrategy.eachDependency { DependencyResolveDetails details ->
            if (details.requested.version) {
                details.useVersion(details.requested.version)
            }
        }
    }
